+func printTrailListEmpty(w io.Writer, authorFilter string, statusFilters []trail.Status) {
+	desc := "No trails found"
+	if len(statusFilters) > 0 {
+		desc = fmt.Sprintf("No %s trails found", trailStatusListDisplay(statusFilters))
