import { sql, type Kysely } from "kysely"

const TABLE_NAME = "repo_trails"
const CONSTRAINT_NAME = "chk_repo_trails_status"
const SIMPLIFIED_STATUS_CHECK = "CHECK (status IN ('draft', 'open', 'merged', 'closed'))"
const LEGACY_STATUS_CHECK =
  "CHECK (status IN ('draft', 'open', 'in_progress', 'in_review', 'merged', 'closed'))"

// lint-acknowledged: DDL_DML_SPLIT_OK — DML touches status only; prior DDL drops unrelated type column.

export async function up(db: Kysely<unknown>): Promise<void> {
  await sql`UPDATE repo_trails SET status = 'open' WHERE status IN ('in_progress', 'in_review')`.execute(
    db,
  )
  await dropCheckIfExists(db, TABLE_NAME, CONSTRAINT_NAME)
  await addCheckIfNotExists(db, TABLE_NAME, CONSTRAINT_NAME, SIMPLIFIED_STATUS_CHECK)
}

export async function down(db: Kysely<unknown>): Promise<void> {
  await dropCheckIfExists(db, TABLE_NAME, CONSTRAINT_NAME)
  await addCheckIfNotExists(db, TABLE_NAME, CONSTRAINT_NAME, LEGACY_STATUS_CHECK)
}

async function dropCheckIfExists(
  db: Kysely<unknown>,
  tableName: string,
  constraintName: string,
): Promise<void> {
  if (!(await constraintExists(db, tableName, constraintName))) return

  try {
    await sql.raw(`ALTER TABLE ${tableName} DROP CHECK ${constraintName}`).execute(db)
  } catch (e: unknown) {
    const message = e instanceof Error ? e.message : ""
    if (message.includes("check that column/key exists") || message.includes("doesn't exist")) {
      return
    }
    throw e
  }
}

async function addCheckIfNotExists(
  db: Kysely<unknown>,
  tableName: string,
  constraintName: string,
  definition: string,
): Promise<void> {
  if (await constraintExists(db, tableName, constraintName)) return
  await sql
    .raw(`ALTER TABLE ${tableName} ADD CONSTRAINT ${constraintName} ${definition}`)
    .execute(db)
}

async function constraintExists(
  db: Kysely<unknown>,
  tableName: string,
  constraintName: string,
): Promise<boolean> {
  const result = await sql<{ count: number | string }>`
    SELECT COUNT(*) AS count
    FROM information_schema.table_constraints
    WHERE table_schema = DATABASE()
      AND table_name = ${tableName}
      AND constraint_name = ${constraintName}
  `.execute(db)

  return Number(result.rows[0]?.count ?? 0) > 0
}

