// ShardParts returns the shard prefix and suffix separately.
// Example: "a3b2c4d5e6f7" -> ("a3", "b2c4d5e6f7")
func (id ID) ShardParts() (shard, suffix string) {
	if len(id) < 3 {
		return string(id), ""
	}
	return string(id[:2]), string(id[2:])
}

// Status represents the lifecycle status of a trail.
type Status string

const (
	StatusDraft      Status = "draft"
	StatusOpen       Status = "open"
	StatusInProgress Status = "in_progress"
	StatusInReview   Status = "in_review"
	StatusMerged     Status = "merged"
	StatusClosed     Status = "closed"
)

// ValidStatuses returns all valid trail statuses in lifecycle order.
func ValidStatuses() []Status {
	return []Status{
		StatusDraft,
		StatusOpen,
		StatusInProgress,
		StatusInReview,
		StatusMerged,
		StatusClosed,
	}
}

// IsValid returns true if the status is a recognized trail status.
func (s Status) IsValid() bool {
	for _, vs := range ValidStatuses() {
		if s == vs {
			return true
		}
	}
	return false
}

// Priority represents the priority level of a trail.
type Priority string

const (
	PriorityUrgent Priority = "urgent"
	PriorityHigh   Priority = "high"
	PriorityMedium Priority = "medium"
	PriorityLow    Priority = "low"
	PriorityNone   Priority = "none"
)

// Type represents the type/category of a trail.
type Type string

const (
	TypeBug      Type = "bug"
	TypeFeature  Type = "feature"
	TypeChore    Type = "chore"
	TypeDocs     Type = "docs"
	TypeRefactor Type = "refactor"
)

// ReviewerStatus represents the review status for a reviewer.
type ReviewerStatus string

const (
	ReviewerPending          ReviewerStatus = "pending"
	ReviewerApproved         ReviewerStatus = "approved"
	ReviewerChangesRequested ReviewerStatus = "changes_requested"
)

// Reviewer represents a reviewer assigned to a trail.
type Reviewer struct {
	Login  string         `json:"login"`
	Status ReviewerStatus `json:"status"`
}

// Author identifies the user who created a trail.
// On the wire the whole object may be null when the original author can no
// longer be resolved (e.g. the GitHub user no longer exists), and login may
// independently be null while the id is retained.
type Author struct {
	ID    string  `json:"id"`
	Login *string `json:"login"`
}

// Metadata represents the metadata for a trail, matching the web PR format.
type Metadata struct {
	Number    int        `json:"number,omitempty"`
	TrailID   ID         `json:"trail_id"`
	Branch    string     `json:"branch"`
	Base      string     `json:"base"`
	Title     string     `json:"title"`
	Body      string     `json:"body"`
	Status    Status     `json:"status"`
	Author    *Author    `json:"author"`
	Assignees []string   `json:"assignees"`
	Labels    []string   `json:"labels"`
	CreatedAt time.Time  `json:"created_at"`
	UpdatedAt time.Time  `json:"updated_at"`
	MergedAt  *time.Time `json:"merged_at"`
	Priority  Priority   `json:"priority,omitempty"`
	Type      Type       `json:"type,omitempty"`
	Reviewers []Reviewer `json:"reviewers,omitempty"`
}

// AuthorLogin returns the trail author's login, or an empty string if the
// author is unknown (object null) or the login is null.
func (m *Metadata) AuthorLogin() string {
	if m == nil || m.Author == nil || m.Author.Login == nil {
		return ""
	}
	return *m.Author.Login
}

// Discussion holds the discussion/comments for a trail.
type Discussion struct {
	Comments []Comment `json:"comments"`
}

// Comment represents a single comment on a trail.
type Comment struct {
	ID         string         `json:"id"`
	Author     string         `json:"author"`
	Body       string         `json:"body"`
	CreatedAt  time.Time      `json:"created_at"`
	Resolved   bool           `json:"resolved"`
	ResolvedBy *string        `json:"resolved_by"`
	ResolvedAt *time.Time     `json:"resolved_at"`
	Replies    []CommentReply `json:"replies,omitempty"`
}

// CommentReply represents a reply to a comment.

package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os/exec"
	"sort"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/trail"

	"charm.land/huh/v2"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/spf13/cobra"
)

const (
	defaultTrailListLimit  = 10
	trailListAuthorMe      = "me"
	defaultTrailListStatus = string(trail.StatusInProgress)
	// trailListStatusAny disables the status filter; user-facing value for --status.
	trailListStatusAny = "any"
)

func newTrailCmd() *cobra.Command {
	var insecureHTTPAuth bool

	cmd := &cobra.Command{
		Use:    "trail",
		Short:  "Manage trails for your branches",
		Hidden: true,
		Args:   cobra.NoArgs,
		Long: `Trails are branch-centric work tracking abstractions. They describe the
"why" and "what" of your work, while checkpoints capture the "how" and "when".

Running 'entire trail' without a subcommand shows the trail for the current
branch, or lists recent trails if no trail exists for the current branch.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailShow(cmd.Context(), cmd.OutOrStdout(), insecureHTTPAuth)
		},
	}

	cmd.PersistentFlags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false,
		"Allow API calls over plain HTTP (insecure, for local development only)")
	if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
		panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
	}

	cmd.AddCommand(newTrailListCmd())
	cmd.AddCommand(newTrailCreateCmd())
	cmd.AddCommand(newTrailUpdateCmd())
	cmd.AddCommand(newTrailFindingCmd())
	cmd.AddCommand(newTrailWatchCmd())

	return cmd
}

// trailInsecureHTTP reads the persistent --insecure-http-auth flag from the trail root command.
func trailInsecureHTTP(cmd *cobra.Command) bool {
	v, _ := cmd.Flags().GetBool("insecure-http-auth") //nolint:errcheck // flag is always registered
	return v
}

// trailListOptions are the inputs to runTrailListAll. Keeping them on a
// struct avoids a long positional argument list at the two call sites.
type trailListOptions struct {
	Author       string
	Status       string
	JSON         bool
	Limit        int
	InsecureHTTP bool
}

func defaultTrailListOptions(insecureHTTP bool) trailListOptions {
	return trailListOptions{
		Status:       defaultTrailListStatus,
		Limit:        defaultTrailListLimit,
		InsecureHTTP: insecureHTTP,
	}
}

// runTrailShow shows the trail for the current branch, or falls through to list.
func runTrailShow(ctx context.Context, w io.Writer, insecureHTTP bool) error {
	branch, err := GetCurrentBranch(ctx)
	if err != nil {
		return runTrailListAll(ctx, w, defaultTrailListOptions(insecureHTTP))
	}

	client, err := NewAuthenticatedAPIClient(ctx, insecureHTTP)
	if err != nil {
		return fmt.Errorf("authentication required: %w", err)
	}

	forge, owner, repo, err := resolveTrailRemote(ctx)
	if err != nil {
		return err
	}

	found, err := findTrailByBranch(ctx, client, forge, owner, repo, branch)
	if err != nil {
		return err
	}
	if found == nil {
		return runTrailListAll(ctx, w, defaultTrailListOptions(insecureHTTP))
	}

	printTrailDetails(w, found.ToMetadata())
	return nil
}

